-- In-transaction verifications (all must return 0):
SELECT COUNT(*) FROM public.orders WHERE final_price < 0;
SELECT COUNT(*) FROM public.orders
WHERE final_price >= 0 AND additional_discount > initial_price;
SELECT COUNT(*) FROM public.orders
WHERE final_price >= 0 AND ABS(final_price - (initial_price - additional_discount)) > 0.005
  AND orderid IN (SELECT orderid FROM price_fix_2026_11_02);
-- Unaffected population unchanged (must equal dry-run values 991860 /
-- 1006994 rows check is informational):
SELECT COUNT(*) FROM public.orders WHERE final_price >= 0;

